def mean_task_score(scores):
    # scores: 每条对话的评分器输出，范围 [0, 1]
    if not scores:
        raise ValueError("empty score list")
    return sum(scores) / len(scores)

def intent_drift_gap(single_turn, evolving_dialogue):
    base = mean_task_score(single_turn)
    drift = mean_task_score(evolving_dialogue)
    return {"single_turn": round(base, 3),
            "evolving": round(drift, 3),
            "gap": round(base - drift, 3)}

# 摘要中的校准集规模与两组分数
print(intent_drift_gap([0.476] * 627, [0.384] * 627))
print(intent_drift_gap([0.467] * 100, [0.367] * 100))

def with_state_maintenance(agent, dialogues):
    scores = []
    for d in dialogues:
        state = agent.estimate_active_requirements(d.history)  # 显式状态
        out = agent.generate(task_state=state)                 # 由状态驱动
        scores.append(d.grader(out))
    return sum(scores) / len(scores)

def baseline_history_only(agent, dialogues):
    scores = []
    for d in dialogues:
        out = agent.generate(history=d.history)
        scores.append(d.grader(out))
    return sum(scores) / len(scores)

def gain(agent, dialogues):
    return (with_state_maintenance(agent, dialogues)
            - baseline_history_only(agent, dialogues))

