import itertools

def power_loss(branches, currents):
    # branches: [(i, j, R), ...]，currents: {(i, j): I}
    total = 0.0
    for i, j, r in branches:
        i_ij = currents.get((i, j), 0.0)
        total += r * i_ij ** 2
    return total

def feasible(u, n_switches, must_close):
    # 简化可行性判断：必须闭合的开关不得断开，联络开关至多合一个
    for k in must_close:
        if u[k] == 0:
            return False
    return sum(u[k] for k in range(n_switches) if k not in must_close) <= 1

def brute_force(n_switches, branches, currents, must_close=(0,)):
    best, best_u = float("inf"), None
    for u in itertools.product([0, 1], repeat=n_switches):
        if not feasible(u, n_switches, must_close):
            continue
        loss = power_loss(branches, currents)
        if loss < best:
            best, best_u = loss, u
    return best_u, best

print(brute_force(3, [(0, 1, 0.2), (1, 2, 0.3)], {(0, 1): 5.0, (1, 2): 3.0}))
